<script setup lang="ts">defineProps<{wallet:{balance:number;held:number;available:number;currency:string}}>();defineEmits<{topup:[amount:number]}>();const amount=ref(1000000);</script><template><section class="wallet-balance" aria-label="موجودی کیف پول"><p>موجودی قابل استفاده</p><strong>{{wallet.available.toLocaleString('fa-IR')}} <small>ریال</small></strong><div><span>کل موجودی {{wallet.balance.toLocaleString('fa-IR')}}</span><span>رزروشده {{wallet.held.toLocaleString('fa-IR')}}</span></div><form @submit.prevent="$emit('topup',amount)"><label>مبلغ افزایش موجودی<input v-model.number="amount" type="number" min="10000" step="10000"></label><button class="primary-button" type="submit">افزایش موجودی</button></form></section></template>
